@tailwind base;
@tailwind components;
@tailwind utilities;

/* Tokens — see docs/ui-design.md §1.1. Slate base + emerald accent. */
@layer base {
  :root {
    --background: 210 40% 98%;            /* slate-50 */
    --foreground: 222.2 84% 4.9%;         /* slate-950 */
    --card: 0 0% 100%;                    /* white — pops over slate-50 */
    --card-foreground: 222.2 84% 4.9%;
    --popover: 0 0% 100%;
    --popover-foreground: 222.2 84% 4.9%;
    --primary: 161 94% 30%;               /* emerald-600 */
    --primary-foreground: 0 0% 100%;
    --secondary: 210 40% 96.1%;           /* slate-100 */
    --secondary-foreground: 222.2 47.4% 11.2%;
    --muted: 210 40% 96.1%;
    --muted-foreground: 215.4 16.3% 46.9%;
    --accent: 210 40% 96.1%;
    --accent-foreground: 222.2 47.4% 11.2%;
    --destructive: 0 72.2% 50.6%;         /* red-600 */
    --destructive-foreground: 0 0% 100%;
    --border: 214.3 31.8% 91.4%;          /* slate-200 */
    --input: 214.3 31.8% 91.4%;
    --ring: 160 84% 39%;                  /* emerald-500 */
    --radius: 0.625rem;                   /* 10px — see ui-design.md §1.3 */
  }

  .dark {
    --background: 222.2 84% 4.9%;         /* slate-950 */
    --foreground: 210 40% 98%;            /* slate-50 */
    --card: 217.2 32.6% 12%;              /* slate-900-ish, lifted off bg */
    --card-foreground: 210 40% 98%;
    --popover: 217.2 32.6% 12%;
    --popover-foreground: 210 40% 98%;
    --primary: 160 84% 39%;               /* emerald-500 — brighter on dark */
    --primary-foreground: 222.2 84% 4.9%;
    --secondary: 217.2 32.6% 17.5%;       /* slate-800 */
    --secondary-foreground: 210 40% 98%;
    --muted: 217.2 32.6% 17.5%;
    --muted-foreground: 215 20.2% 65.1%;
    --accent: 217.2 32.6% 17.5%;
    --accent-foreground: 210 40% 98%;
    --destructive: 0 62.8% 30.6%;         /* red-700-ish */
    --destructive-foreground: 210 40% 98%;
    --border: 217.2 32.6% 17.5%;          /* slate-800 */
    --input: 217.2 32.6% 17.5%;
    --ring: 158 64% 52%;                  /* emerald-400 — most visible focus */
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
    font-feature-settings: "cv11", "ss01";
  }
}

